+namespace Orders.Api.Services;
+
+public sealed class RefundClient(ILogger<RefundClient> logger)
+{
+    public async Task<bool> RefundAsync(int orderId, decimal amount, CancellationToken cancellationToken)
+    {
+        try
+        {
+            using var client = new HttpClient();
+            using var response = await client.PostAsJsonAsync("https://payments.example.com/refunds", new { orderId, amount }, cancellationToken);
+            response.EnsureSuccessStatusCode();
+
+            logger.LogInformation("Refunded {Amount} for order {OrderId}", amount, orderId);
+            return true;
+        }
+        catch
+        {
+            return false;
+        }
+    }
+}
